# Cotizador (web): solo se entra con la cuenta de hetnacnc.com. El correo y la contraseña
# propios del Cotizador quedan escondidos para empleados invitados a un taller.
# Uso: python3 aplicar_solo_tienda.py   (dentro de la carpeta del repo Cotizador)
import sys
def cambia(p, viejo, nuevo):
    s = open(p, encoding="utf-8").read()
    if s.count(viejo) != 1: sys.exit("No encontre el texto a cambiar en " + p)
    open(p, "w", encoding="utf-8").write(s.replace(viejo, nuevo))
cambia('lib/screens/login_screen.dart', '  bool _reenviando = false;\n\n', '  bool _reenviando = false;\n  // En la web se entra con la cuenta de hetnacnc.com (una sola cuenta). El\n  // correo y la contraseña propios del Cotizador quedan sólo para empleados\n  // invitados a un taller (y para la app de Android/iOS).\n  bool _conContrasena = !kIsWeb;\n\n')
cambia('lib/screens/login_screen.dart', '\n                      // Correo\n', "\n                      if (!_conContrasena) ...[\n                        SizedBox(width: double.infinity, height: 50,\n                          child: ElevatedButton.icon(\n                            onPressed: () => _irATienda('/api/app/entrar-cotizador'),\n                            icon: const Icon(Icons.storefront_outlined, size: 20, color: Colors.white),\n                            label: Text(tr('Entrar con mi cuenta de hetnacnc.com'),\n                              style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w700,\n                                color: Colors.white)),\n                            style: ElevatedButton.styleFrom(\n                              backgroundColor: AppColors.azul,\n                              shape: RoundedRectangleBorder(\n                                borderRadius: BorderRadius.circular(10))))),\n                        const SizedBox(height: 8),\n                        Text(tr('Usa la misma cuenta de la tienda. Si todavía no tienes, ahí mismo la creas.'),\n                          style: const TextStyle(fontSize: 12, color: AppColors.textoSecundario),\n                          textAlign: TextAlign.center),\n                        const SizedBox(height: 14),\n                        Center(child: TextButton(\n                          onPressed: () => setState(() => _conContrasena = true),\n                          child: Text(tr('¿Te invitaron como empleado de un taller? Entra aquí'),\n                            style: const TextStyle(fontSize: 12,\n                              color: AppColors.textoSecundario,\n                              fontWeight: FontWeight.w600)))),\n                      ],\n\n                      if (_conContrasena) ...[\n                      // Correo\n")
cambia('lib/screens/login_screen.dart', "                        decoration: InputDecoration(\n                          labelText: tr('Contrasena'),\n                          prefixIcon: const Icon(Icons.lock_outline,\n", "                        decoration: InputDecoration(\n                          labelText: tr('Contraseña'),\n                          prefixIcon: const Icon(Icons.lock_outline,\n")
cambia('lib/screens/login_screen.dart', "\n                      // Una sola cuenta (en hetnacnc.com/cotizador/): entra con\n                      // la cuenta de la tienda, sin otra contraseña.\n                      if (kIsWeb) ...[\n                        const SizedBox(height: 6),\n                        Row(children: [\n                          const Expanded(child: Divider()),\n                          Padding(padding: const EdgeInsets.symmetric(horizontal: 10),\n                            child: Text(tr('o'), style: const TextStyle(\n                              fontSize: 12, color: AppColors.textoSecundario))),\n                          const Expanded(child: Divider()),\n                        ]),\n                        const SizedBox(height: 10),\n                        SizedBox(width: double.infinity, height: 46,\n                          child: OutlinedButton.icon(\n                            onPressed: () => _irATienda('/api/app/entrar-cotizador'),\n                            icon: const Icon(Icons.storefront_outlined, size: 18),\n                            label: Text(tr('Entrar con mi cuenta de hetnacnc.com'),\n                              style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),\n                            style: OutlinedButton.styleFrom(\n                              foregroundColor: AppColors.azul,\n                              side: const BorderSide(color: AppColors.azul),\n                              shape: RoundedRectangleBorder(\n                                borderRadius: BorderRadius.circular(10))))),\n                        const SizedBox(height: 4),\n                        Text(tr('La misma cuenta de la tienda: sin otra contraseña.'),\n                          style: const TextStyle(fontSize: 11, color: AppColors.textoSecundario),\n                          textAlign: TextAlign.center),\n                      ],\n", '\n                      // En la web, regresar a "entrar con la cuenta de la tienda"\n                      if (kIsWeb)\n                        Center(child: TextButton(\n                          onPressed: () => setState(() { _conContrasena = false; _error = null; }),\n                          child: Text(tr(\'← Entrar con mi cuenta de hetnacnc.com\'),\n                            style: const TextStyle(fontSize: 12,\n                              color: AppColors.azul, fontWeight: FontWeight.w600)))),\n                      ],\n')
cambia('lib/i18n/en.dart', "  'Contrasena': 'Password',\n  'Contraseña *': 'Password *',\n", "  'Contrasena': 'Password',\n  'Contraseña': 'Password',\n  'Contraseña *': 'Password *',\n")
cambia('lib/i18n/en.dart', "  // Una sola cuenta (login web)\n  'o': 'or',\n  'Entrar con mi cuenta de hetnacnc.com': 'Sign in with my hetnacnc.com account',\n", "  // Una sola cuenta (login web)\n  'Entrar con mi cuenta de hetnacnc.com': 'Sign in with my hetnacnc.com account',\n")
cambia('lib/i18n/en.dart', "  'Entrar con mi cuenta de hetnacnc.com': 'Sign in with my hetnacnc.com account',\n  'La misma cuenta de la tienda: sin otra contraseña.': 'Same account as the store: no extra password.',\n};\n", "  'Entrar con mi cuenta de hetnacnc.com': 'Sign in with my hetnacnc.com account',\n  'Usa la misma cuenta de la tienda. Si todavía no tienes, ahí mismo la creas.': 'Use your store account. If you don\\'t have one yet, you can create it there.',\n  '¿Te invitaron como empleado de un taller? Entra aquí': 'Invited as a shop employee? Sign in here',\n  '← Entrar con mi cuenta de hetnacnc.com': '← Sign in with my hetnacnc.com account',\n};\n")
